export async function processUnifiedAgentToolCalls(params: {
  toolCalls: OpenAI.Chat.ChatCompletionMessageToolCall[];
  workspaceId: string;
  contactId: string;
  phone: string;
  context?: UnknownRecord;
  allowedTools?: string[];
  executeTool: (
    workspaceId: string,
    contactId: string,
    phone: string,
    tool: string,
    args: ToolArgs,
    context?: UnknownRecord,
  ) => Promise<unknown>;
  logAutopilotEvent: (
    workspaceId: string,
    contactId: string,
    tool: string,
    args: Record<string, unknown>,
    result: unknown,
  ) => Promise<unknown>;
  logger: StructuredLogger;
}): Promise<ActionEntry[]> {
  const actionsList: ActionEntry[] = [];

  await forEachSequential(params.toolCalls, async (toolCall) => {
    if (toolCall.type !== 'function') {
      return;
    }
    const toolName = toolCall.function.name;
    if (!isAllowedTool(toolName, params.allowedTools)) {
      params.logger.warn(
        `Blocked disallowed agent tool call: workspaceId=${params.workspaceId} tool=${toolName}`,
      );
      const blockedResult = { blocked: true, reason: 'capability_not_allowed' };
      actionsList.push({ tool: toolName, args: {}, result: blockedResult });
      await params.logAutopilotEvent(
        params.workspaceId,
        params.contactId,
        toolName,
        {},
        blockedResult,
      );
      return;
    }
    let toolArgs: Record<string, unknown> = {};
    try {
      toolArgs = parseToolArgs(toolCall.function.arguments);
      if (toolArgs && typeof toolCall.function.arguments === 'string' && toolCall.function.arguments.trim() && Object.keys(toolArgs).length === 0 && toolCall.function.arguments.trim() !== '{}') {
        params.logger.warn(`Failed to parse tool args for ${toolName}`);
      }
    } catch {
      params.logger.warn(`Failed to parse tool args for ${toolName}`);
    }
    const result = await params.executeTool(
      params.workspaceId,
      params.contactId,
      params.phone,
      toolName,
      toolArgs,
      params.context,
    );
    actionsList.push({ tool: toolName, args: toolArgs, result });
    await params.logAutopilotEvent(
      params.workspaceId,
      params.contactId,
      toolName,
      toolArgs,
      result,
    );
  });

  return actionsList;
}

